import { useScrollReveal } from "../hooks/useScrollReveal";
import { useTheme } from "../context/ThemeContext";

// ─────────────────────────────────────────────────────────────────────────────
// CERTIFICATIONS — edit this array to manage your certs.
// Set `completed: false` to hide a cert until it's earned.
// ─────────────────────────────────────────────────────────────────────────────
const certifications = [
  {
    id: "cert-01",
    completed: true,
    title: "Web Development Fundamentals",
    org: "Issuing Organization",
    year: "2024",
    credential: null,
    image: "/images/certs/cert-web-dev.svg",
    imageAlt: "Web Development Fundamentals certificate",
    tags: ["PHP", "MySQL", "HTML/CSS", "JavaScript"],
  },
  {
    id: "cert-02",
    completed: true,
    title: "Mobile App Development",
    org: "Issuing Organization",
    year: "2024",
    credential: null,
    image: "/images/certs/cert-mobile-dev.svg",
    imageAlt: "Mobile App Development certificate",
    tags: ["Flutter", "Firebase", "Dart"],
  },
  {
    id: "cert-03",
    completed: true,
    title: "Database Management & Design",
    org: "Issuing Organization",
    year: "2023",
    credential: null,
    image: "/images/certs/cert-database.svg",
    imageAlt: "Database Management & Design certificate",
    tags: ["SQL", "Normalization", "Query Optimization"],
  },
];

function CertCard({ cert, isDark }) {
  return (
    <article className={`group flex flex-col rounded-xl overflow-hidden border transition-all duration-200
      ${isDark
        ? "bg-ink-800 border-wire hover:border-ink-500"
        : "bg-white border-wire-light hover:border-neutral-300 hover:shadow-md"}`}>

      {/* Image */}
      <div className="relative overflow-hidden" style={{ aspectRatio: "16/9" }}>
        <img src={cert.image} alt={cert.imageAlt} width="800" height="500" loading="lazy"
             className="w-full h-full object-cover transition-transform duration-500 ease-out group-hover:scale-[1.03]" />
        <div className={`absolute top-3 right-3 font-mono text-[11px] px-2 py-0.5 rounded
          ${isDark ? "bg-ink-950/85 text-neutral-400 border border-wire" : "bg-white/90 text-neutral-500 border border-wire-light"}`}>
          {cert.year}
        </div>
      </div>

      {/* Body */}
      <div className="flex flex-col flex-1 p-5">
        <h3 className={`font-semibold text-[0.9375rem] tracking-tight mb-1
          ${isDark ? "text-neutral-200" : "text-neutral-800"}`}>
          {cert.title}
        </h3>
        <p className={`text-sm mb-4 ${isDark ? "text-neutral-500" : "text-neutral-500"}`}>
          {cert.org}
        </p>

        <div className="flex flex-wrap gap-1.5 mb-5">
          {cert.tags.map((tag) => (
            <span key={tag} className="tag tag-primary">{tag}</span>
          ))}
        </div>

        <div className={`mt-auto pt-4 border-t flex items-center justify-between
          ${isDark ? "border-wire" : "border-wire-light"}`}>
          <div className="flex items-center gap-1.5 font-mono text-[11px]"
               style={{ color: "var(--primary)" }}>
            <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5">
              <polyline points="20 6 9 17 4 12"/>
            </svg>
            Completed
          </div>

          {cert.credential ? (
            <a href={cert.credential} target="_blank" rel="noopener noreferrer"
               className="font-mono text-[11px] tracking-wider flex items-center gap-1.5 transition-colors"
               style={{ color: "var(--primary)" }}
               aria-label={`Verify ${cert.title}`}>
              Verify
              <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                <path d="M18 13v6a2 2 0 01-2 2H5a2 2 0 01-2-2V8a2 2 0 012-2h6M15 3h6v6M10 14L21 3"/>
              </svg>
            </a>
          ) : (
            <span className={`font-mono text-[11px] ${isDark ? "text-neutral-700" : "text-neutral-300"}`}>
              Credential pending
            </span>
          )}
        </div>
      </div>
    </article>
  );
}

export default function Certifications() {
  const { ref, revealed } = useScrollReveal();
  const { theme } = useTheme();
  const isDark = theme === "dark";
  const completed = certifications.filter((c) => c.completed);
  if (completed.length === 0) return null;

  return (
    <section id="certifications"
      className={`py-32 border-t transition-colors duration-300
        ${isDark ? "bg-ink-950 border-wire" : "bg-paper-50 border-wire-light"}`}>
      <div className="max-w-6xl mx-auto px-6">

        <div className="mb-16">
          <p className="section-label mb-5">Certifications</p>
          <h2 className={`section-title text-4xl lg:text-5xl max-w-xl
            ${isDark ? "text-neutral-100" : "text-neutral-900"}`}>
            Formal recognition<br />
            <span className={isDark ? "text-neutral-500" : "text-neutral-400"}>of applied skills.</span>
          </h2>
        </div>

        <div ref={ref}
             className={`${revealed ? "fade-up visible" : "fade-up"} grid sm:grid-cols-2 lg:grid-cols-3 gap-5`}>
          {completed.map((cert) => (
            <CertCard key={cert.id} cert={cert} isDark={isDark} />
          ))}
        </div>

        <p className={`mt-8 font-mono text-[11px] tracking-wider
          ${isDark ? "text-neutral-700" : "text-neutral-400"}`}>
          {certifications.length - completed.length > 0
            ? `${certifications.length - completed.length} in progress — shown when completed`
            : "Additional certifications added as completed"}
        </p>
      </div>
    </section>
  );
}
